let ultimoNumero = $json.ultimoNumero ?? null;

function gerarNumeroBaixaRepeticao() {
  let numero;
  do {
    numero = Math.floor(Math.random() * (10 - 5 + 1)) + 5;
  } while (numero === ultimoNumero && Math.random() < 0.9);

  ultimoNumero = numero;
  return numero;
}

const numeroGerado = gerarNumeroBaixaRepeticao();

return [
  {
    json: {
      numero: numeroGerado
    },
  },
];

